import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";
import { flyGeospatialCameraToAsync, setGeospatialOrientation } from "@babylonjs/lite";

export interface Place { yaw: number; pitch: number; radius: number; center: { x: number; y: number; z: number } }

interface FlightState {
  token: number;
  stopped: boolean;
  stop: () => void;
  dispose: () => void;
}

const activeFlights = new WeakMap<GeospatialCamera, FlightState>();
let nextToken = 0;

const ANGULAR_EPSILON = 1e-3;
const LINEAR_EPSILON = 1e-3;

function normalizeAngle(angle: number): number { ... }
function shortestAngleDiff(a,b) { ... }
