function arrived(...) { ... }

function installCancelFlyWatch(camera: GeospatialCamera, notify: () => void): () => void { ... }

function stopPreviousFlight(camera: GeospatialCamera): void {
  const previous = activeFlights.get(camera);
  if (!previous) return;
  previous.stop();
  previous.dispose();
  if (activeFlights.get(camera) === previous) activeFlights.delete(camera);
}

function cancelAnyFly(camera: GeospatialCamera): void {
  if (typeof camera._cancelFly === "function") {
    camera._cancelFly();
  }
}

export async function flyToPlace(...): Promise<boolean> {
  const duration = Number.isFinite(durationMs) ? Math.max(0, durationMs) : 0;
  stopPreviousFlight(camera);
  cancelAnyFly(camera);

  if (duration <= 0) {
    try {
      setGeospatialOrientation(camera, place);
    } catch {
      return false;
    }
    return arrived(camera, place);
  }

  const token = ++nextToken;
  let resolveStop!: (value: boolean) => void;
  const stopPromise = new Promise<boolean>((resolve) => { resolveStop = resolve; });
  let stopped = false;
  const stop = () => { if (!stopped) { stopped = true; resolveStop(false); } };
  const flight: FlightState = { token, stopped, stop, dispose: () => {} };
  activeFlights.set(camera, flight);

  let flyPromise: Promise<void>;
  try {
    flyPromise = flyGeospatialCameraToAsync(camera, scene, {
      yaw: place.yaw,
      pitch: place.pitch,
      radius: place.radius,
      center: place.center,
      durationMs: duration,
    });
  } catch {
    if (activeFlights.get(camera) === flight) activeFlights.delete(camera);
    return false;
  }

  const flyResult = flyPromise.then(() => {
    if (activeFlights.get(camera) !== flight || stopped) return false;
    return arrived(camera, place);
  }).catch(() => false);

  const uninstallWatch = installCancelFlyWatch(camera, () => {
    if (activeFlights.get(camera) === flight) stop();
  });
  flight.dispose = () => { uninstallWatch(); };

  if (activeFlights.get(camera) !== flight && !stopped) {
    stopped = true;
    resolveStop(false);
  }

  const result = await Promise.race([flyResult, stopPromise]);

  if (activeFlights.get(camera) === flight) {
    flight.dispose();
    activeFlights.delete(camera);
  } else {
    flight.dispose();
  }

  return result;
}
