import { flyGeospatialCameraToAsync } from "@babylonjs/lite";

export interface Place { ... }

interface FlightState { stopped: boolean; stop: () => void; dispose: () => void; }
const activeFlights = new WeakMap<GeospatialCamera, FlightState>();
const ANGULAR_EPSILON = 1e-3;
const LINEAR_EPSILON = 1e-3;

function normalizeAngle(angle: number): number { ... }
function angleDiff(a,b) { ... }
function isFiniteNumber(value: number): boolean { return Number.isFinite(value); }
function nearlyEqualCenter(a: {x:number;y:number;z:number}, b: {x:number;y:number;z:number}) { ... }
function arrived(camera: GeospatialCamera, place: Place): boolean { ... }

function stopPreviousFlight(camera: GeospatialCamera): void { ... }
function cancelAnyFly(camera: GeospatialCamera): void { ... }
function installCancelFlyWatch(...): () => void { ... }

export async function flyToPlace(...): Promise<boolean> {
  let flight: FlightState | undefined;
  try {
    const duration = Number.isFinite(durationMs) ? Math.max(0, durationMs) : 0;
    const center = place.center as unknown as typeof camera.center;
    stopPreviousFlight(camera);
    cancelAnyFly(camera);

    if (duration <= 0) {
      try { camera._setOrientation(place.yaw, place.pitch, place.radius, center); } catch { return false; }
      return arrived(camera, place);
    }

    let resolveStop!: (value: boolean) => void;
    const stopPromise = new Promise<boolean>((resolve) => { resolveStop = resolve; });
    let stopped = false;
    let allowStop = false;
    const stop = () => { if (!stopped) { stopped = true; resolveStop(false); } };
    flight = { stopped, stop, dispose: () => {} };
    activeFlights.set(camera, flight);

    const notify = () => { if (allowStop && activeFlights.get(camera) === flight) stop(); };
    const uninstallWatch = installCancelFlyWatch(camera, notify);
    flight.dispose = () => { uninstallWatch(); };

    let flyPromise: Promise<void>;
    try {
      flyPromise = flyGeospatialCameraToAsync(camera, scene, {
        yaw: place.yaw,
        pitch: place.pitch,
        radius: place.radius,
        center,
        durationMs: duration,
      });
    } catch {
      return false;
    }

    const flyResult = flyPromise.then(() => {
      if (activeFlights.get(camera) !== flight || stopped) return false;
      return arrived(camera, place);
    }).catch(() => false);

    allowStop = true;
    if (activeFlights.get(camera) !== flight && !stopped) {
      stopped = true;
      resolveStop(false);
    }

    return await Promise.race([flyResult, stopPromise]);
  } catch {
    return false;
  } finally {
    if (flight) {
      try { flight.dispose(); } catch {}
      if (activeFlights.get(camera) === flight) activeFlights.delete(camera);
    }
  }
}
