import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";
import { flyGeospatialCameraToAsync, setGeospatialOrientation } from "@babylonjs/lite";

export interface Place { yaw: number; pitch: number; radius: number; center: { x: number; y: number; z: number } }

interface FlightState { stop: () => void; dispose: () => void; }

const activeFlights = new WeakMap<GeospatialCamera, FlightState>();
const ANGULAR_EPSILON = 1e-3;
const LINEAR_EPSILON = 1e-3;

function normalizeAngle(angle: number): number {
  const twoPi = Math.PI * 2;
  let a = angle % twoPi;
  if (a > Math.PI) a -= twoPi;
  else if (a < -Math.PI) a += twoPi;
  return a;
}

function angleDiff(a: number, b: number): number {
  return Math.abs(normalizeAngle(a - b));
}

function finite(n: number): boolean { return Number.isFinite(n); }

function nearlyEqualCenter(a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }): boolean {
  return finite(a.x) && finite(a.y) && finite(a.z) && finite(b.x) && finite(b.y) && finite(b.z) &&
    Math.abs(a.x - b.x) <= LINEAR_EPSILON && Math.abs(a.y - b.y) <= LINEAR_EPSILON && Math.abs(a.z - b.z) <= LINEAR_EPSILON;
}

function arrived(camera: GeospatialCamera, place: Place): boolean {
  if (!finite(place.yaw) || !finite(place.pitch) || !finite(place.radius) || !finite(camera.yaw) || !finite(camera.pitch) || !finite(camera.radius)) return false;
  const radiusEpsilon = Math.max(LINEAR_EPSILON, Math.abs(place.radius) * 1e-6);
  return angleDiff(camera.yaw, place.yaw) <= ANGULAR_EPSILON &&
    angleDiff(camera.pitch, place.pitch) <= ANGULAR_EPSILON &&
    Math.abs(camera.radius - place.radius) <= radiusEpsilon &&
    nearlyEqualCenter(camera.center, place.center);
}

function stopPreviousFlight(camera: GeospatialCamera): void {
  const previous = activeFlights.get(camera);
  if (!previous) return;
  try { previous.stop(); } catch {}
  try { previous.dispose(); } catch {}
  if (activeFlights.get(camera) === previous) activeFlights.delete(camera);
}

