export async function flyToPlace(camera: GeospatialCamera, scene: SceneContext, place: Place, durationMs: number): Promise<boolean> {
  let flight: FlightState | undefined;
  try {
    const duration = Number.isFinite(durationMs) ? Math.max(0, durationMs) : 0;
    const center = place.center as unknown as typeof camera.center;

    stopPreviousFlight(camera);
    cancelAnyFly(camera);

    if (duration <= 0) {
      try {
        setGeospatialOrientation(camera, { yaw: place.yaw, pitch: place.pitch, radius: place.radius, center });
      } catch {
        return false;
      }
      return arrived(camera, place);
    }

    let resolveStop!: (value: boolean) => void;
    const stopPromise = new Promise<boolean>((resolve) => { resolveStop = resolve; });
    let stopped = false;
    let allowStop = false;
    const stop = () => {
      if (!stopped) {
        stopped = true;
        resolveStop(false);
      }
    };

    flight = { stop, dispose: () => {} };
