    };

    const uninstallWatch = installCancelFlyWatch(camera, notify);
    flight.dispose = () => { uninstallWatch(); };

    let flyPromise: Promise<void>;
    try {
      flyPromise = flyGeospatialCameraToAsync(camera, scene, {
        yaw: place.yaw,
        pitch: place.pitch,
        radius: place.radius,
        center,
        durationMs: duration,
      });
    } catch {
      return false;
    }

    const flyResult = flyPromise.then(() => {
      if (activeFlights.get(camera) !== flight || stopped) return false;
      return arrived(camera, place);
